def toc(items):
 return ''.join(f'<a class="toc-row" href="#{p["id"]}"><span>{html.escape(p["title"])}</span><span class="num">{lookup[p["id"]]}</span></a>' for p in items)
pages[2]['html']='<div class="toc-group">Dasar penggunaan</div>'+toc([intro])+'<div class="toc-group">Aturan dan kontrol aplikasi</div>'+toc(rules)+'<div class="toc-group">Lampiran operasional</div>'+toc(end)+'<div class="note">Klik judul atau nomor halaman untuk berpindah. Setiap halaman memiliki tautan <b>Daftar isi</b> di bagian bawah.</div>'
# Two columns maintain a compact, readable index for the 43 screen pages.
half=(len(guides)+1)//2
pages[3]['html']='<div class="cols"><div>'+toc(guides[:half])+'</div><div>'+toc(guides[half:])+'</div></div>'
parts=[]
for i,p in enumerate(pages,1):
 kind=p.get('kind','appendix');klass='page '+kind
 content=p.get('html','')
 if kind!='cover':
  eyebrow={'toc':'Navigasi dokumen','rules':'Bagian I · Aturan aplikasi','guide':'Bagian II · Penggunaan aplikasi','appendix':'Lampiran operasional'}.get(kind,'Panduan operasional')
  head=f'<div class="eyebrow">{eyebrow}</div><h1>{html.escape(p["title"])}</h1>'
  if p.get('subtitle'):head+=f'<p class="subtitle">{html.escape(p["subtitle"])}</p>'
  if p.get('route'):head+=f'<p class="route">{html.escape(p["route"])}</p>'
  if p.get('image'):
   filename=p['image'];filename=filename if filename.endswith('.png') else filename+'.png'
   if not (out/'screenshots'/filename).exists():raise ValueError('Missing image '+filename)
   head+=f'<figure><img src="screenshots/{filename}" alt="{html.escape(p["title"])}"><figcaption>Screenshot aplikasi · data simulasi · 26 Oktober 2026</figcaption></figure>'
  content=head+'<div class="body">'+content+'</div>'
 foot=f'<div class="footer"><span>Cloud POS · Pengadaan sampai penerimaan</span><span><a href="#daftar-isi">Daftar isi</a> &nbsp; | &nbsp; {i:02}</span></div>'
 parts.append(f'<section class="{klass}" id="{p["id"]}"><div class="content">{content}</div>{foot}</section>')
(out/'panduan-pengadaan-penerimaan.html').write_text('<!doctype html><html lang="id"><meta charset="UTF-8"><title>Panduan Pengadaan sampai Penerimaan — Cloud POS</title><style>'+style+'</style><body>'+''.join(parts)+'</body></html>')
